def min_operations_to_equal(a):
    operations = 0
    for i in range(1, len(a)):
        diff = a[0] - a[i]
        if diff > 0:
            while diff % 2 == 0:
                diff //= 2
            if diff > a[0]:
                operations += 1
            a[i] += diff
    return operations

