from collections import defaultdict

def find_cycle_edges(n, edges):
    gr = defaultdict(list)
    for u, v in edges:
        gr[u-1].append(v-1)
        gr[v-1].append(u-1)

    def dfs(parent, vertex):
        visited[vertex] = True
        for neighbor in gr[vertex]:
            if visited[neighbor] and neighbor != parent:
                return True
            if not visited[neighbor]:
                cycle_exists = dfs(vertex, neighbor)
                if cycle_exists:
                    return True
        return False

    count = 0
    visited = [False] * n
    for vertex in range(n):
        if not visited[vertex]:
            if dfs(-1, vertex):
                count += 1
    return count

