from typing import List

def find_articulation_points(n: int, m: int) -> List[int]:
    edges = []
    result = 0
    odds = 0

    for _ in range(m):
        u, v = map(int, input().split())
        if u > v:
            u, v = v, u

        if u == n or v == n:
            return 0

        edges.append([min(u, v), max(u, v)])

    for i, edge in enumerate(edges):
        u, v = edge
        for j in range(i + 1, len(edges)):
            if edges[j][0] != u and edges[j][0] != v and edges[j][1] != u and edges[j][1] != v:
                if u == min(edge[0], edge[1]) and v == max(edge[0], edge[1]):
                    if edges[j][0] == u and edges[j][1] == v:
                        continue
                    if edges[j][0] == v and edges[j][1] == u:
                        continue
                elif v == min(edge[0], edge[1]) and u == max(edge[0], edge[1]):
                    if edges[j][0] == v and edges[j][1] == u:
                        continue
                    if edges[j][0] == u and edges[j][1] == v:
                        continue
                elif edges[i] == edges[j]:
                    continue

                if leaf_pick_edge(edges[i], edges[j]):
                    result += 1
                    edges[i][1] = "-1"
                    edges[j][1] = "-1"
                else:
                    odds += 1

    return result

def leaf_pick_edge(a, b):
    if a[0] > b[0] and a[0] > a[1] and b[0] > b[1]:
        return a
    elif b[0] > a[0] and b[0] > b[1] and a[0] > a[1]:
        return b

n, m = map(int, input().split())
print(find_articulation_points(n, m))
