from itertools import permutations
from collections import defaultdict

def is_valid_coloring(grid):
    color_counts = defaultdict(int)
    for row in grid:
        for color in row:
            color_counts[color] += 1
    return len({color_counts[color] for color in color_counts}) == 1

def get_neighbors(grid, i, j):
    neighbors = []
    if i > 0:
        neighbors.append((i - 1, j))
    if j > 0:
        neighbors.append((i, j - 1))
    if i < len(grid) - 1:
        neighbors.append((i + 1, j))
    if j < len(grid[0]) - 1:
        neighbors.append((i, j + 1))
    if i > 0 and j > 0:
        neighbors.append((i - 1, j - 1))
    if i > 0 and j < len(grid[0]) - 1:
        neighbors.append((i - 1, j + 1))
    if i < len(grid) - 1 and j > 0:
        neighbors.append((i + 1, j - 1))
    if i < len(grid) - 1 and j < len(grid[0]) - 1:
        neighbors.append((i + 1, j + 1))
    return neighbors

def solve(grid):
    n, m = len(grid), len(grid[0])
    if not is_valid_coloring(grid):
        return "0"

    available_colors = list(range(1, len(grid) * m + 1))
    colored_grid = [["0"] * m for _ in range(n)]
    used_colors = set()

    def backtrack(i, j):
        if i == n or j == m:
            return False

        for color in available_colors:
            if color in used_colors:
                continue
            used_colors.add(color)
            for x, y in get_neighbors(grid, i, j):
                colored_grid[i][x] = str(color)
                colored_grid[x][j] = str(color)
                if backtrack(x, y):
                    return True
                else:
                    colored_grid[i][x] = "0"
                    colored_grid[x][j] = "0"
            used_colors.remove(color)
            break

        return False

    backtrack(0, 0)
    return "\n".join("".join(row) for row in colored_grid)

