            for _ in range(2, 2 * N + 1):
                if time <= requests[i] and maximum_gradient < requests[i + 1] - time:
                    maximum_gradient = requests[i + 1] - time
            events.remove(time + T - maximum_gradient)
            heapq.heappush(events, time + T - maximum_gradient)
            max_requests += 1

    print(' '.join(map(str, requests).zfill(8)[:N]), sep=' ')

