def lexicographically_smallest_string(s, k):
    arr = list(s)
    for _ in range(k - 1):
        for _ in range(math.ceil(len(s) / k)):
            index = 0
            arr_chunk = ''
            while index < len(s):
                if arr[index] == 'a':
                    if index != 0 and arr[index - 1] == 'b':
                        if index + 1 < len(arr) and arr[index + 1] == 'a':
                            arr_chunk += 'b'
                            index += 2
                        else:
                            index += 1
                    else:
                        arr_chunk += 'a'
                        if arr_chunk.endswith('a') and arr_chunk.endswith('b') and arr_chunk.endswith('c'):
                            arr_chunk = arr_chunk[:-2]
                            arr_chunk += 'c'
                        else:
                            arr_chunk += 'c'
                else:
                    if arr[index] == 'a':
                        arr_chunk += arr[index]
                    else:
                        arr_chunk += 'a'
                    if index != len(s) - 1 and arr[index + 1] == 'a':
                        arr_chunk += 'b'
                        break
                index += 1

            arr_chunk = arr_chunk[::-1]
            arr = [elem if elem == 'a' else arr_chunk.remove('b') for elem in arr]
