def is_feasible(colors):
    # Check if a graph coloring is feasible
    n, m = len(colors), len(colors[0])
    colored = [[0] * m for _ in range(n)]

    def is_safe(x, y, col):
        # Check if a vertex is completely colored with the given color
        if colored[x][y] in [col - 1, 0]:
            return False
        return all(
            (
                (x + dy, y + dx) if colors[x + dy][y + dx] == 0
                else True
                for dx in [-1, 1] for dy in [-1, 1]
            ) and colors[x + dy][y + dx] not in [col - 1, 0]
        )

    for x in range(n):
        for y in range(m):
            for col in [1, 2, 3]:
                if is_safe(x, y, col):
                    colored[x][y] = col
                    break

