def guess_number(n, r, known_numbers):
    # If the zombie is in rank 1, guess the number they see on the forehead of the highest-ranking zombie.
    if r == 1:
        return max(known_numbers)
    else:
        # For zombies in higher ranks, use a binary search to guess their own number.
        left, right = 1, n
        while left < right:
            mid = (left + right) // 2
            if summation_of_numbers(mid, [1] + known_numbers, n, r) > summation_of_numbers(mid, [1] + known_numbers, n, n):
                right = mid
            else:
                left = mid + 1
        return right if left == n else left

# Helper function to sum numbers for a given guess
