def combination(n, k):
    return factorial(n) // (factorial(k) * factorial(n - k))

def count_good_permutations(n, k):
    # calculate the number of bad positions
    bad_positions = combination(n, k) * (n - k)
    # check if the number of bad positions is less than or equal to n
    if bad_positions <= n:
        return combination(n, k)
    else:
        return combination(n, k) - combination(bad_positions - 1, k)

