def count_permutations(n, k):
    if k == 0:
        return 1
    elif k > n:
        return 0
    if n == 1:
        return 0 if k != 0 else 1

    dp = [0] * (n + 1)
    dp[n] = 1

    for i in range(n-1, -1, -1):
        for j in range(i, n+1):
            if (abs(i - j) == 1 and j - i < k):
                dp[i] = (dp[i] + dp[j+1]) % mod

    return dp[0]

