def solution(T, N, A):
    MOD = 10**9 + 7
    @lru_cache(maxsize=None)
    def dp(i, last_level):
        if i == N:
            return 1
        if last_level == -1 or A[i] != -1:
            return dp(i + 1, A[i]) % MOD
        count = 0
        for level in range(1, N + 1):
            if level != last_level:
                count += dp(i + 1, level) % MOD
        return count % MOD
    return [dp(0, -1) % MOD for _ in range(T)]

