from typing import List

def calculate_ways(levels: List[int]) -> int:
    """
    Calculate the number of ways to fill missing levels in levels array to form a valid game.
    levels is a list of integers where -1 represents missing levels.
    """
    total_ways = 1
    unfinished_levels = set()

    for i in range(len(levels)):
        if levels[i] == -1:
            unfinished_levels.add(i)

    while unfinished_levels:
        infinity_in_queue = False
        for level in unfinished_levels:
            i = level
            can_overtake = False
            while i + 1 < len(levels) and levels[i + 1] != -1:
                if levels[i + 1] >= levels[i]:
                    can_overtake = True
                i += 1
            if not can_overtake:
                break
        else:
            return 0
        for level in unfinished_levels.copy():
            if not i - 1 < level:
                continue
            if levels[level] == -1:
                continue
            if levels[level] == levels[i - 1]:
                continue
            if levels[level] < levels[i - 1]:
                levels[i] = levels[level]
            else:
                levels[i] = levels[i - 1]
        unfinished_levels -= {level for level in unfinished_levels if levels[level] == -1}
        current_level = levels[-1]
        for f in levels.copy():
            if f == -1:
                continue
            if f > 0 and f < current_level:
                levels[f] = levels[-1]
            if f > current_level:
                break
        if levels[-1] - 1 >= finished_levels:
            return 0
        if levels != finished_levels:
            total_ways *= 2
        finished_levels += set(range(len(levels)))

    return total_ways

