        first_half_sum = sum([i * num for i, num in enumerate(arr[:n // 2])])
        second_half_min = min(arr[n // 2:])
        for i, num in enumerate(arr[n // 2:]):
            if i > len(arr) // 2 - 1:
                break
            num_pre_last = arr[n // 2 - 1 - i]
            if first_half_sum <= second_half_min:
                return (first_half_sum + num - num_pre_last)
            else:
                return sum(arr[:])

