from collections import defaultdict

def find(parent, i):
    if parent[i] == i:
        return i
    return find(parent, parent[i])

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        elif rootX == rootY:
            return
        if rank[rootX] == rank[rootY]:
            rank[rootY] += 1
        parent[rootY] = rootX

def detectSimpleCycle(edges, adj_list, n):
    # Initialize parent and rank arrays
    parent = defaultdict(int)
    rank = [0] * n
    simple_edges = []

    # Union statistic
    edge_used = [0] * n

    v = -1
    l = len(edges)
    for i in range(n):
        parent[i] = i
    for i in range(l):
        u, v = edges[i]
        u -= 1
        v -= 1

        if v < 0 or u < 0:
            break
        edge_used[find(parent, u)] = 1  # Indicate this edge is used
        edge_used[find(parent, v)] = 1

        if u == v:
            # Cycle found when both ends are same
            v += 1
            simple_edges.append(i + 1)
        elif find(parent, u) != find(parent, v):
            # Find the union
            union(parent, rank, u, v)

    print(len(simple_edges))
    print(' '.join(map(str, simple_edges)))

def main():
