    edges = [tuple(map(int, input().split())) for _ in range(m)]
    adj_list = [[] for _ in range(n)]
    seen = [False] * n

    for i in range(m):
        u, v = edges[i]
        if seen[u]:
            adj_list[u - 1].append(i + 1)
        seen[u - 1] = True
        if seen[v]:
            adj_list[v - 1].append(i + 1)

    detectSimpleCycle(edges, adj_list, n)

