import sys

def find_path_or_cycle(edges, start, reverse=False):
    if reverse:
        stack = [start]
        seen_edges = set()
    else:
        stack = [start - 1] * len(edges)  # Assuming 1-based indexing
        seen_edges = {start - 1}

    path = []

    while stack:
        current = stack[-1]

        if reverse:
            if current not in seen_edges:
                seen_edges.add(current)
                if edges[current] <= current:
                    return path
                else:
                    stack.append(edges[current] - 1)
                    path.append(edges[current])

            else:
                break

        else:
            if current not in seen_edges:
                seen_edges.add(current)
                if edges[current] >= current:
                    return path
                else:
                    stack.append(edges[current] - 1)
                    path.append(edges[current])

            else:
                break

    return None

def simple_cycles(edges):
    n = len(edges) + 1
    cycles = []

    stack = [0] * (n - 1)  # 0-based indexing
    seen = {0}

    while stack:
        start = stack.pop()
        path = find_path_or_cycle(edges, start)
        if path:
            cycles.append(path)

    return cycles

