from math import log10, pow

def solve(n, k):
    mod = int(1e9) + 7
    # Calculate the base case for the recurrence relation
    def dp(i, count, used):
        if count > i or i > n:
            return 0
        if i == n and count == k:
            return 1
        if i > n:
            return 0
        if not used[i-1]:
            used[i-1] = True
            return dp(i + 1, count, used) + dp(i + 1, count + 1, used)
        else:
            return dp(i + 1, count, used)

    used = [False] * n
    return dp(1, 0, used) % mod

