def partition(x, n):
    return [''.join(''.join(sorted(x[0:i])) for i in range(n+1)) for i in range(1, n+1)]

def recurse(substring, n, open_close):
    if len(substring) < n:
        return ''
    if n == 1:
        return '%s\0%s' % (open_close,substring)
    else:
        new_length = len(substring) % n
        partition_ = partition(substring[:new_length+1], n)
        partition_[-1] = partition_[len(substring) % new_length][-1] if len(partition_[-1]) > 1 else partition_[len(substring) % new_length][0]
        return ','.join([recurse(s, n-1, open_close+'') for s in partition_[:-1]])+','

